CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY AUTOINCREMENT,national_id TEXT UNIQUE NOT NULL,first_name TEXT NOT NULL,last_name TEXT NOT NULL,grade TEXT NOT NULL,field TEXT DEFAULT '',class_name TEXT DEFAULT '',photo TEXT DEFAULT '',password_hash TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS classes(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,teacher TEXT DEFAULT '',weekday TEXT DEFAULT '',time TEXT DEFAULT '',online_url TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS enrollments(student_id INTEGER NOT NULL,class_id INTEGER NOT NULL,PRIMARY KEY(student_id,class_id));
CREATE TABLE IF NOT EXISTS grades(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,subject TEXT NOT NULL,score REAL NOT NULL,term TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS consents(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',updated_at TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT DEFAULT '',audience TEXT DEFAULT 'all',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exams(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,subject TEXT NOT NULL,exam_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER,title TEXT NOT NULL,url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,subject TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS counselor_audio(id INTEGER PRIMARY KEY AUTOINCREMENT,url TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_students_national_id ON students(national_id);
CREATE INDEX IF NOT EXISTS idx_grades_student ON grades(student_id);
